export default function ({ type, participants }) {
  const q = [];
  if (type) q.push("type=" + encodeURIComponent(type));
  if (participants) q.push("participants=" + encodeURIComponent(participants));
  if (!q.length) throw Error("Provide a type or participants");
  return { url: "https://bored-api.appbrewery.com/filter?" + q.join("&") };
}

